package org.com.sharekhan.analysis;
import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
class IndexHistoryDailyStoreTest {
 JdbcTemplate db;IndexHistoryDailyStore store;final LocalDate day=IndexIntradayBarsTest.DAY;final Instant now=Instant.parse("2026-10-30T14:00:00Z");
 @BeforeEach void setup(){var ds=new DriverManagerDataSource("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=PostgreSQL;DB_CLOSE_DELAY=-1","sa","");db=new JdbcTemplate(ds);store=new IndexHistoryDailyStore(db,new DataSourceTransactionManager(ds));store.initialize();}
 List<IndexIntradayBars.Candle> bars(int i){return IndexIntradayBars.parse(IndexIntradayBarsTest.data(i,IndexIntradayBarsTest.window()),i,IndexIntradayBarsTest.window());}
 @Test void writesBothIntervalsAtomicallyPreservesOldProviderAndRepeatedSavesAreIdempotent(){
  var j=new IndexHistoryDailyStore.Job("NIFTY",day);db.update("INSERT INTO market_history_candles(id,symbol,candle_time,interval_minutes,open_price,high_price,low_price,close_price,provider) VALUES ('old','NIFTY',?,5,200,202,198,201,'MSTOCK')",day.atTime(9,15));store.plan(j);assertThat(store.claim(j,now)).isTrue();store.save(j,IndexIntradayBarsTest.window(),bars(1),bars(5),now,now);assertThat(store.complete("NIFTY",IndexIntradayBarsTest.window())).isTrue();assertThat(db.queryForObject("SELECT count(*) FROM market_history_candles",Integer.class)).isEqualTo(450);assertThat(db.queryForObject("SELECT close_price FROM market_history_candles WHERE id='old'",Double.class)).isEqualTo(201);assertThat(store.latestCommon("NIFTY")).isEqualTo(day);
  assertThat(store.claim(j,now.plusSeconds(1801))).isTrue();store.save(j,IndexIntradayBarsTest.window(),bars(1),bars(5),now.plusSeconds(1801),now.plusSeconds(1801));assertThat(db.queryForObject("SELECT count(*) FROM market_history_candles",Integer.class)).isEqualTo(450);
 }
 @Test void failedPairTransactionDoesNotLeaveHalfWrittenDay(){var j=new IndexHistoryDailyStore.Job("NIFTY",day);store.plan(j);store.claim(j,now);assertThatThrownBy(()->store.save(j,IndexIntradayBarsTest.window(),bars(1).subList(0,374),bars(5),now,now)).isInstanceOf(Exception.class);assertThat(db.queryForObject("SELECT count(*) FROM market_history_candles",Integer.class)).isZero();}
 @Test void durableLeaseAndSuccessfulResponseCacheSurviveAnotherInstance(){var j=new IndexHistoryDailyStore.Job("NIFTY",day);store.plan(j);assertThat(store.claim(j,now)).isTrue();store.checkpoint(j,now,5,"public-data-json",true);store.fail(j,now,now,"Delayed one-minute data");var other=new IndexHistoryDailyStore(db,new DataSourceTransactionManager(Objects.requireNonNull(db.getDataSource())));assertThat(other.claim(j,now.plusSeconds(60))).isFalse();assertThat(other.checkpoints(j).fiveValid()).isTrue();assertThat(other.pending(day)).contains(j);assertThat(other.claim(j,now.plusSeconds(1801))).isTrue();assertThatThrownBy(()->store.checkpoint(j,now,1,"stale worker",true)).hasMessageContaining("lease");}
}
